#!/usr/bin/env node
'use strict'

// Two-context collaboration acceptance for the performance-repair build.
// Uses only the existing isolated PostgreSQL/Redis services and creates or
// deletes rooms whose exact keys are generated by this process.

const fs = require('fs')
const path = require('path')
const http = require('http')
const net = require('net')
const { spawn, fork, execFileSync } = require('child_process')
const { randomUUID, createHash } = require('crypto')

const ROOT = path.resolve(__dirname, '..')
const APP_DIR = path.join(ROOT, 'simple-mind-map')
const API_SERVER = path.join(APP_DIR, 'bin', 'collabServer.js')
const MCP_SERVER = path.join(APP_DIR, 'bin', 'mcpServer.mjs')
const BUILD_DIR = path.resolve(process.env.PERFORMANCE_REPAIR_BUILD_DIR || path.join(ROOT, 'output', 'performance-repair-20261013', 'build'))
const DEPENDENCY_DIR = path.join(ROOT, 'output', 'performance-repair-20261013', 'dependencies', 'node_modules')
const OUTPUT_BASE = path.join(ROOT, 'output', 'performance-repair-20261013', 'browser')
const PG = Object.freeze({
  host: '127.0.0.1', port: 25492, database: 'mcp_incremental_test',
  user: 'mcp_test', password: 'mcp-incremental-test-db-password'
})
const REDIS_URL = 'redis://127.0.0.1:16389'
const API_PORT = 19094
const MCP_PORT = 19095
const runId = `${new Date().toISOString().replace(/[:.]/g, '-')}-${randomUUID().slice(0, 8)}`
const runDir = path.join(OUTPUT_BASE, runId)
const summaryPath = path.join(runDir, 'summary.json')
const eventsPath = path.join(runDir, 'events.jsonl')

function assert(condition, message) {
  if (!condition) throw new Error(message)
}

function append(value) {
  fs.appendFileSync(eventsPath, JSON.stringify({ at: new Date().toISOString(), ...value }) + '\n')
}

function fileHash(file) {
  return createHash('sha256').update(fs.readFileSync(file)).digest('hex')
}

function directoryHash(directory) {
  const hash = createHash('sha256')
  const files = []
  const visit = current => {
    for (const entry of fs.readdirSync(current, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const fullPath = path.join(current, entry.name)
      if (entry.isDirectory()) visit(fullPath)
      else if (entry.isFile()) files.push(fullPath)
    }
  }
  visit(directory)
  for (const file of files) {
    hash.update(path.relative(directory, file).replace(/\\/g, '/'))
    hash.update('\0')
    hash.update(fs.readFileSync(file))
    hash.update('\0')
  }
  return { sha256: hash.digest('hex'), fileCount: files.length }
}

function available(port) {
  return new Promise((resolve, reject) => {
    const server = net.createServer()
    server.once('error', error => reject(new Error(`端口 ${port} 已被占用：${error.code || error.message}`)))
    server.listen(port, '127.0.0.1', () => server.close(error => error ? reject(error) : resolve()))
  })
}

function loadPlaywright() {
  const candidates = [
    path.join(DEPENDENCY_DIR, 'playwright'),
    path.join(DEPENDENCY_DIR, '@playwright', 'test'),
    path.join(APP_DIR, 'node_modules', 'playwright'),
    path.join(APP_DIR, 'node_modules', '@playwright', 'test')
  ]
  for (const candidate of candidates) {
    try {
      const loaded = require(candidate)
      if (loaded && loaded.chromium) return loaded
    } catch (_) {}
  }
  throw new Error(`Playwright 未找到，检查 ${DEPENDENCY_DIR}`)
}

async function verifyTestServices() {
  const { Pool } = require(path.join(APP_DIR, 'node_modules', 'pg'))
  const { createClient } = require(path.join(APP_DIR, 'node_modules', 'redis'))
  const pool = new Pool({ ...PG, max: 1, connectionTimeoutMillis: 4000 })
  const redis = createClient({ url: REDIS_URL, socket: { connectTimeout: 4000 } })
  redis.on('error', () => {})
  try {
    const result = await pool.query('select current_database() as database, current_user as username')
    assert(result.rows[0].database === PG.database && result.rows[0].username === PG.user,
      '隔离 PostgreSQL 目标不匹配，拒绝继续')
    await redis.connect()
    assert((await redis.ping()) === 'PONG', '隔离 Redis 未通过 PING 检查')
    return { database: result.rows[0].database, username: result.rows[0].username, redis: REDIS_URL }
  } finally {
    await redis.quit().catch(() => {})
    await pool.end().catch(() => {})
  }
}

